                        'autoStartReviewConfigFile'
                    ]
                });
            } catch (e) {
                console.warn('⚠️ autoStartReview trigger failed:', e.message || e);
            }
        }
        if (!autoStarted) {
            autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
        }

        console.log('✅ Test rework complete — re-run:', testStatus, '→', targetStatus);

        // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
        // wrote outputs/*_usage.json during the agent run.
        try {
            tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            testStatus: testStatus,
            jiraStatus: targetStatus,
            ticketKey: ticketKey
        };

    } catch (error) {
        console.error('❌ Error in postTestReworkResults:', error);
        try {
            const key = (params.ticket || (params.jobParams && params.jobParams.ticket) || {}).key;
            if (key) {
                var resume = feedbackLoop.resumeAgent({
                    ticketKey: key,
                    customParams: customParams,
                    section: 'postAction',
                    stage: 'test_rework_post_action',
                    error: error.toString()
                });
                if (resume.attempted) {
                    return action(params);
                }
                // Flavor follows the ticket's tracker (gh-770); the
                // customParams const may be uninitialized (TDZ) if the
                // failure predates its declaration, so resolve defensively.
                var catchCustomParams =
                    (params.jobParams && params.jobParams.customParams) || params.customParams || {};
                var em = commentMarkup.forTicket(key, catchCustomParams);
                trackersModule.createTracker(config, catchCustomParams).postComment(
                    key,
                    em.h(3, '❌ Test Rework Error') + '\n\n' + em.code(error.toString())
                );
            }
        } catch (e) {}
        releaseLock();
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action,
        resolveCustomParams,
        commitIfNeeded,
        commitAndPush,
        buildTestReworkResultComment
    };
}

