function buildReworkStartedComment(flavor, ctx) {
    var m = flavor;
    var comment = m.h(3, '🔧 Automated Rework Started') + '\n\n' +
        m.bold('Pull Request') + ': ' + m.link('PR #' + ctx.prNumber, ctx.prUrl) + '\n' +
        m.bold('Branch') + ': ' + m.code(ctx.branchName) + '\n\n';

