+        assert.equal(plan.skip, true);
+        assert.ok(plan.reason.indexOf('github') !== -1, 'reason names the provider');
+        assert.ok(plan.reason.indexOf('parent = {ticketKey}') !== -1, 'reason names the skipped query');
+    });
