/**
 * Single owner of the GitHub issue key-shape convention (gh-770).
 *
 * The machine loop keys GitHub-backed tickets with these shapes:
 *   gh-N           — the router key convention (gh-1308)
 *   owner/repo#N   — composite form (acme/widgets#12)
 *   #N             — bare-hash form (dispatch payloads)
 *   N              — bare issue number
 *
 * This list was previously synchronized by hand across four regex lists
 * (commentMarkup flavor detection, validateInputJql's gate and its inline
 * extraction alternation, trackers.js's issue-number parser). Drift surfaced
 * only as a live leg silently losing its tracker updates — exactly the bug
 * class gh-770 fixes — so every consumer now derives from THIS module:
 *
 *   - commentMarkup.flavorForTicket  → isGitHubKeyShape(key)
 *   - validateInputJql gate          → isGitHubKeyShape(key)
 *   - validateInputJql extraction    → shapeSources() alternation
 *   - trackers.js githubIssueNumber  → githubIssueNumberIn(key)
 *
 * Adding a shape is a one-line change here; the derivation is pinned by
 * js/unit-tests/test_ticketKeyShapes.js plus per-consumer derivation tests.
 *
 * GraalJS-compatible: var declarations, plain functions, no arrow functions.
 */
'use strict';

// Ordered is-shape list — also the extraction order: gh-N before bare N so a
// router key keeps its original case (uppercasing would mint 'GH-12', a key
// different from the 'gh-12' the machine loop created), and composite forms
// before bare numbers.
var GITHUB_KEY_SHAPES = [
    /^gh-\d+$/i,               // gh-1308 — GitHub router key convention
    /^[\w.-]+\/[\w.-]+#\d+$/,  // acme/widgets#12
    /^#\d+$/,                  // #12
    /^\d+$/                    // 12
];

// The same shapes with the numeric issue part captured, in the SAME order —
// trackers.js parses issue numbers from this list so a key that passes the
// is-shape check can never die with "cannot parse GitHub issue key".
var GITHUB_KEY_CAPTURE_SHAPES = [
    /^gh-(\d+)$/i,
    /^[\w.-]+\/[\w.-]+#(\d+)$/,
    /^#(\d+)$/,
    /^(\d+)$/
];

/**
 * True when the key matches one of the GitHub issue key shapes.
 * Null/undefined/empty are not shapes.
 * @param {string} key
 * @returns {boolean}
 */
function isGitHubKeyShape(key) {
    var k = String(key == null ? '' : key).trim();
    for (var i = 0; i < GITHUB_KEY_SHAPES.length; i++) {
        if (GITHUB_KEY_SHAPES[i].test(k)) return true;
    }
    return false;
}

/**
 * Parse the numeric GitHub issue number out of any GitHub-shaped key.
 * @param {string} key
 * @returns {number|null} the issue number, or null when the key is not a
 *                        GitHub key shape
 */
function githubIssueNumberIn(key) {
    var k = String(key == null ? '' : key).trim();
    for (var i = 0; i < GITHUB_KEY_CAPTURE_SHAPES.length; i++) {
        var m = GITHUB_KEY_CAPTURE_SHAPES[i].exec(k);
        if (m) return parseInt(m[1], 10);
    }
    return null;
}

/**
 * Anchor-stripped source fragments of the shape list, in order, for building
 * inline alternations — e.g. validateInputJql extracts the ticket key from a
 * JQL string with `new RegExp('key\\s*(?:=|in\\s*\\()\\s*(' +
 * shapeSources().join('|') + ')', 'i')`, keeping the alternation derived
 * instead of copy-pasted.
 * @returns {string[]}
 */
function shapeSources() {
    var out = [];
    for (var i = 0; i < GITHUB_KEY_SHAPES.length; i++) {
        out.push(GITHUB_KEY_SHAPES[i].source.replace(/^\^/, '').replace(/\$$/, ''));
    }
    return out;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        GITHUB_KEY_SHAPES: GITHUB_KEY_SHAPES,
        isGitHubKeyShape: isGitHubKeyShape,
        githubIssueNumberIn: githubIssueNumberIn,
        shapeSources: shapeSources
    };
}

/**
 * Validates the ticket key embedded in an inputJql string, and verifies the
 * ticket actually exists in Jira.  Call this from a preJSAction so the agent
 * aborts with a clear error instead of silently processing a missing or
 * placeholder ticket (e.g. the default "key = JD-82").
 *
 * GraalJS-compatible: var declarations, plain functions, no arrow functions.
 */

// Accepts PROJECT-123 or PROJECT_CODE-123 (uppercase project key, numeric id)
var TICKET_KEY_RE = /^[A-Z][A-Z0-9_]*-\d+$/;

// GitHub issue key shapes have a single owner (gh-770):
// common/ticketKeyShapes.js. The gate below consults its isGitHubKeyShape()
// and the extractor builds its alternation from shapeSources() — a local
// copy here would drift the next time a shape is added.
var ticketKeyShapes = require('./ticketKeyShapes.js');

// Jira-speak alternation first (uppercase normalization applies), then the
// GitHub shapes so gh-N keys keep their original case — uppercasing would
// mint 'GH-12', a different key from the 'gh-12' the machine loop created.
// (A Jira project literally keyed 'GH' is unaffected: its keys already match
// the Jira shape unchanged.)
var KEY_EXTRACTION_RE = new RegExp(
    'key\\s*(?:=|in\\s*\\()\\s*([A-Z][A-Z0-9_]*-\\d+|' +
    ticketKeyShapes.shapeSources().join('|') + ')',
    'i'
);

/**
 * Extract the ticket key from an inputJql string.
 * Handles "key = KEY", "key in (KEY)" and the GitHub key shapes.
 * @param {string} jql
 * @returns {string|null}
 */
function extractTicketKeyFromJql(jql) {
    if (!jql || typeof jql !== 'string') return null;
    var m = jql.match(KEY_EXTRACTION_RE);
    if (!m || !m[1]) return null;
    // The Jira branch is case-insensitive, so it can also match a gh-N key —
    // the shape check therefore decides: GitHub keys return as written (no
    // 'GH-12' minting), everything else is a Jira key and uppercases.
    return ticketKeyShapes.isGitHubKeyShape(m[1]) ? m[1] : m[1].toUpperCase();
}

/**
 * Throw if key is null or does not match an expected ticket key format
 * (Jira PROJECT-123 or a GitHub issue key shape).
 * @param {string|null} key
 */
function validateTicketKeyFormat(key) {
    if (!key || (!TICKET_KEY_RE.test(key) && !ticketKeyShapes.isGitHubKeyShape(key))) {
        throw new Error('Invalid or missing ticket key: "' + key +
            '". Expected a Jira key (PROJECT-123) or a GitHub issue key (gh-123, owner/repo#123, #123, 123)');
    }
}

/**
 * Fetch the ticket via jira_get_ticket and throw if it does not exist.
 * @param {string} key  Validated ticket key
 * @returns {Object}    The ticket object
 */
function requireTicketExists(key) {
    var ticket;
    try {
        ticket = jira_get_ticket({ key: key });
    } catch (e) {
        throw new Error('Ticket not found: ' + key + ' — ' + (e.message || e));
    }
    if (!ticket || !ticket.key) {
        throw new Error('Ticket not found: ' + key);
    }
    return ticket;
}

/**
 * Convenience wrapper: read inputJql from params, validate the key format,
 * and verify the ticket exists.
 * @param {Object} params  jobParams or full params block containing inputJql
 * @returns {Object}       The Jira ticket object
 */
function validateAndRequireTicket(params) {
    var jobParams = (params && params.jobParams) ? params.jobParams : params;
    var inputJql = (jobParams && jobParams.inputJql) || '';
    var key = extractTicketKeyFromJql(inputJql);
    validateTicketKeyFormat(key);
    return requireTicketExists(key);
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        extractTicketKeyFromJql: extractTicketKeyFromJql,
        validateTicketKeyFormat: validateTicketKeyFormat,
        requireTicketExists: requireTicketExists,
        validateAndRequireTicket: validateAndRequireTicket
    };
}

